"""Procedural Morblass rig parts + rig.json (water wraith: hooded head, long arms, a flowing wave skirt). Original art generated by this
script (no legacy pixels used). Run: python3 tools/assets/rig-gen/morblass.py <out_rig_dir>  (needs Pillow + numpy)
Look matches the Fiara/Pax/Treenoc rigs: layered flow streaks in the shared water ramp (palette.py), a near-black navy outline, a pale-cyan
upper-left rim light, foam-white wave crests and a dark hollow face with two cold eye slits.
"""
import json, os, sys, zlib
import numpy as np
from PIL import Image, ImageDraw, ImageFilter
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import palette

OUT = sys.argv[1]
os.makedirs(os.path.join(OUT, "parts"), exist_ok=True)
SS = 4
W = 80 * SS
WATER = palette.ELEMENT_RAMPS["water"]
RAMP = [(0.0, WATER[0]), (0.3, WATER[1]), (0.58, WATER[2]), (0.82, WATER[3]), (1.0, WATER[4])]
OUTLINE = np.array(palette.outline("water"), np.float32)
RIM = np.array((190, 240, 255), np.float32)
FACE = (6, 12, 30)
EYE = (170, 240, 255)

# geometry in the 80x80 rest frame, E view (y down)
G = {
 "tail": dict(pts=[(10,62),(18,52),(30,48),(46,50),(58,58),(68,70),(62,79),(48,75),(34,79),(20,77),(8,72)], joint=(34,56), z=1, parent=None, bias=-0.12, waves=True),
 "armB": dict(pts=[(38,30),(47,29),(55,37),(63,47),(70,55),(66,60),(58,55),(48,48),(40,40)], joint=(43,32), z=2, parent="torso", bias=-0.2),
 "torso": dict(pts=[(20,60),(18,46),(22,31),(31,24),(42,26),(49,35),(51,47),(55,60),(40,64)], joint=(35,44), z=5, parent="tail", bias=0.0, waves=True),
 "head": dict(pts=[(33,23),(37,10),(45,5),(54,9),(57,19),(52,28),(41,29)], joint=(45,24), z=7, parent="torso", bias=0.05),
 "armF": dict(pts=[(21,30),(30,28),(35,39),(33,51),(38,62),(31,68),(23,63),(20,51),(17,40)], joint=(27,31), z=8, parent="torso", bias=0.1),
}

def view_tf(view, part):
    if view == "E":
        return dict(sx=1.0, dx=-3 if part == "head" else 0, dy=0)
    if view == "SE":
        d = dict(sx=0.93, dx=2, dy=1)
        if part == "head": d = dict(sx=1.06, dx=-8, dy=4, scale=1.06)
        if part == "armF": d = dict(sx=0.95, dx=-3, dy=1)
        if part == "armB": d = dict(sx=0.95, dx=3, dy=1)
        if part == "torso": d = dict(sx=0.96, dx=1, dy=2)
        return d
    d = dict(sx=0.93, dx=-1, dy=-1)  # NE: seen from behind
    if part == "head": d = dict(sx=0.92, dx=-6, dy=-2, scale=0.94)
    if part == "armF": d = dict(sx=0.95, dx=1, dy=-1)
    if part == "armB": d = dict(sx=0.95, dx=2, dy=-1)
    if part == "torso": d = dict(sx=1.0, dx=-2, dy=-1)
    return d

def apply(tf, p, c=(40, 40)):
    s = tf.get("scale", 1.0)
    return (c[0] + (p[0] - c[0]) * tf["sx"] * s + tf["dx"], c[1] + (p[1] - c[1]) * s + tf["dy"])

def noise(rs, scale, sx=1, sy=1):
    """Smooth noise, stretched sx/sy times (flow streaks)."""
    h = max(2, W // (scale * sy) + 2); w = max(2, W // (scale * sx) + 2)
    small = rs.rand(h, w)
    return np.asarray(Image.fromarray((small * 255).astype(np.uint8)).resize((W, W), Image.BICUBIC), np.float32) / 255.0

def render(name, view, pts, g, seed):
    m = Image.new("L", (W, W), 0)
    d = ImageDraw.Draw(m)
    d.polygon([(x * SS, y * SS) for x, y in pts], fill=255)
    if g.get("waves"):  # curling spray tips along the lower edge
        ys = max(p[1] for p in pts)
        xs = sorted(p[0] for p in pts)
        for i in range(5):
            bx = xs[0] + (xs[-1] - xs[0]) * (i + 0.5) / 5
            d.polygon([((bx - 3) * SS, (ys - 3) * SS), ((bx + 3) * SS, (ys - 4) * SS), ((bx + 5) * SS, (ys - 9 - (i % 2) * 3) * SS)], fill=255)
    m = m.filter(ImageFilter.GaussianBlur(SS * 0.35))
    ma = np.asarray(m, np.float32) / 255.0
    rs = np.random.RandomState(seed)
    flow = noise(rs, 5, 4, 1) if name in ("tail", "torso") else noise(rs, 5, 1, 3)  # streaks run with the body
    fine = noise(rs, 2)
    yy, xx = np.mgrid[0:W, 0:W].astype(np.float32) / W
    t = 0.78 - 0.55 * yy - 0.2 * xx + 0.5 * (flow - 0.5) + 0.12 * (fine - 0.5) + g["bias"] + 0.28
    # foam-white wave crests: thin bright sinusoidal bands
    if g.get("waves"):
        band = np.abs(np.sin((yy * 9.0 + 0.6 * np.sin(xx * 14.0 + seed)) * np.pi)) > 0.965
        t = np.where(band, t + 0.3, t)
    # cel-band into 6 steps so it reads as the baked look, not a smooth gradient
    t = np.clip(np.round(np.clip(t, 0, 1) * 5.0) / 5.0, 0, 1)
    rgb = palette.ramp(RAMP, t)
    inner = np.asarray(m.filter(ImageFilter.MinFilter(SS * 2 + 1)), np.float32) / 255.0
    edge = np.clip(np.subtract(ma, inner), 0, 1)
    shifted = np.roll(np.roll(ma, SS * 2, axis=0), SS * 2, axis=1)
    lit = np.clip(np.subtract(ma, shifted), 0, 1) * inner.clip(0, 1)
    lit = np.asarray(Image.fromarray((lit * 255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(SS * 0.5)), np.float32) / 255.0
    rgb = rgb * (1 - 0.85 * edge[..., None]) + OUTLINE[None, None, :] * (0.85 * edge[..., None])
    rgb = rgb * (1 - 0.7 * lit[..., None]) + RIM[None, None, :] * (0.7 * lit[..., None])
    return Image.fromarray(np.dstack([np.clip(rgb, 0, 255), ma * 255.0]).astype(np.uint8), "RGBA")

def face(im, tf, view):
    d = ImageDraw.Draw(im)
    x0, y0 = apply(tf, (42, 12)); x1, y1 = apply(tf, (57, 26))
    d.ellipse([x0 * SS, y0 * SS, x1 * SS, y1 * SS], fill=FACE + (255,))  # hooded hollow
    for ex, ey in ((47, 17), (53, 19)):
        x, y = apply(tf, (ex, ey))
        d.ellipse([x * SS - 2.2 * SS, y * SS - 1.2 * SS, x * SS + 2.2 * SS, y * SS + 1.2 * SS], fill=EYE + (255,))

parts = []
for view in ("E", "SE", "NE"):
    tfs = {k: view_tf(view, k) for k in G}
    for k, g in G.items():
        pts = [apply(tfs[k], p) for p in g["pts"]]
        im = render(k, view, pts, g, zlib.crc32((k + view).encode()) % 9973 + 7)
        if k == "head" and view != "NE":
            face(im, tfs[k], view)
        small = im.resize((80, 80), Image.LANCZOS)
        a = np.asarray(small)
        ys, xs = np.nonzero(a[..., 3] > 8)
        x0, x1, y0, y1 = int(xs.min()), int(xs.max()) + 1, int(ys.min()), int(ys.max()) + 1
        crop = small.crop((x0, y0, x1, y1))
        fname = f"{k}.png" if view == "E" else f"{k}_{view.lower()}.png"
        crop.save(os.path.join(OUT, "parts", fname))
        parts.append(dict(view=view, id=k, png=fname, joint=apply(tfs[k], g["joint"]), off=(x0, y0), size=crop.size))

byv = {v: {e["id"]: e for e in parts if e["view"] == v} for v in ("E", "SE", "NE")}
def pv(e):
    return [int(round(e["joint"][0])) - e["off"][0], int(round(e["joint"][1])) - e["off"][1]]
def at(v, pid):
    g = G[pid]; e = byv[v][pid]
    jx, jy = int(round(e["joint"][0])), int(round(e["joint"][1]))
    if g["parent"] is None:
        return [jx, jy]
    pe = byv[v][g["parent"]]
    return [jx - int(round(pe["joint"][0])), jy - int(round(pe["joint"][1]))]

rig_parts = []
for pid in ["head", "armF", "torso", "tail", "armB"]:
    g = G[pid]
    p = {"id": pid}
    if g["parent"]: p["parent"] = g["parent"]
    p["png"] = byv["E"][pid]["png"]; p["pivot"] = pv(byv["E"][pid]); p["at"] = at("E", pid); p["z"] = g["z"]
    p["views"] = {v: {"png": byv[v][pid]["png"], "pivot": pv(byv[v][pid]), "at": at(v, pid)} for v in ("SE", "NE")}
    rig_parts.append(p)

def c(**kw): return kw
actions = {
 "idle": dict(frames=4, curves={
    "tail": c(dy=[0, 1, 1, 0]),
    "torso": c(rot=[0, 1, 1, 0], dy=[0, 0, 1, 1]),
    "head": c(rot=[0, -1, -2, -1]),
    "armF": c(rot=[0, 2, 3, 1]),
    "armB": c(rot=[0, -2, -3, -1]),
 }),
 "walk": dict(frames=4, curves={  # glides: the skirt sways and the arms trail
    "tail": c(rot=[-3, 0, 3, 0], dy=[0, 1, 0, 1]),
    "torso": c(rot=[2, 2, 2, 2], dy=[1, 0, 1, 0]),
    "head": c(rot=[-2, -1, -2, -1]),
    "armF": c(rot=[8, 0, -10, 0]),
    "armB": c(rot=[-10, 0, 8, 0]),
 }),
 # water buff: both arms sweep up and forward, the body rises, then crashes down
 "cast": dict(frames=4, curves={
    "torso": c(rot=[0, -3, -3, 2], dy=[0, -1, -2, 1]),
    "head": c(rot=[-1, -5, -4, 2]),
    "armF": c(rot=[-10, -40, -62, -20]),
    "armB": c(rot=[-8, -34, -52, -16]),
    "tail": c(dy=[0, 0, -1, 1]),
 }),
}
json.dump(dict(dirs=["E", "SE", "NE"], parts=rig_parts, actions=actions), open(os.path.join(OUT, "rig.json"), "w"), indent=2)
open(os.path.join(OUT, "license.txt"), "w").write(
"""Rig parts for morblass: original art generated by tools/assets/rig-gen/morblass.py (WP-art-consistency-batches, 2026-11-12, Claude). No pixels
are copied; silhouette and colours chosen by eye after the legacy public/assets/img/map/morblass.png. Licence: same as the
repository's own original code and art (still to be decided in README.md; owner to confirm).
""")
print("ok")
